(function () {
  const _rs = rng || random;
  function R() { return _rs(); }
  function RR(a, b) { return a + (b - a) * _rs(); }
  function RI(a, b) { return Math.floor(RR(a, b + 1)); }

  function hash2(x, y) {
    let n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
    return n - Math.floor(n);
  }
  function smooth(t) { return t * t * (3 - 2 * t); }
  function vn(x, y) {
    const xi = Math.floor(x), yi = Math.floor(y);
    const xf = x - xi, yf = y - yi;
    const a = hash2(xi, yi), b = hash2(xi + 1, yi);
    const c = hash2(xi, yi + 1), d = hash2(xi + 1, yi + 1);
    const u = smooth(xf), v = smooth(yf);
    return a * (1 - u) * (1 - v) + b * u * (1 - v) + c * (1 - u) * v + d * u * v;
  }
  function fbm(x, y, oct) {
    let s = 0, amp = 0.5, f = 1;
    for (let i = 0; i < oct; i++) { s += amp * vn(x * f, y * f); f *= 2.03; amp *= 0.5; }
    return s;
  }

  // ---------- Sky ----------
  const sky = ctx.createLinearGradient(0, 0, 0, H * 0.72);
  sky.addColorStop(0, '#8fa4bc');
  sky.addColorStop(0.35, '#a7b9cb');
  sky.addColorStop(0.7, '#c6d2dc');
  sky.addColorStop(1, '#dfe6e8');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  // soft clouds
  for (let i = 0; i < 22; i++) {
    const cx = RR(0, W), cy = RR(20, H * 0.42);
    const w = RR(140, 340), h = RR(8, 22);
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, w * 0.55);
    const a = RR(0.08, 0.2);
    g.addColorStop(0, `rgba(248,246,240,${a})`);
    g.addColorStop(0.6, `rgba(240,238,235,${a * 0.4})`);
    g.addColorStop(1, 'rgba(240,238,235,0)');
    ctx.fillStyle = g;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(1, h / w);
    ctx.beginPath();
    ctx.arc(0, 0, w, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // ---------- helpers ----------
  function polyPath(pts) {
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
    ctx.closePath();
  }

  // ---------- far ranges ----------
  function farRange(baseY, amp, colorTop, colorBot, offset) {
    const pts = [];
    const n = 60;
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      const x = t * W;
      const nz = fbm(t * 5 + offset, offset * 3, 4);
      const y = baseY - (nz * 0.7 + Math.sin(t * 6 + offset) * 0.15 + 0.2) * amp;
      pts.push([x, y]);
    }
    const path = [...pts, [W, H], [0, H]];
    const g = ctx.createLinearGradient(0, baseY - amp, 0, baseY + 100);
    g.addColorStop(0, colorTop);
    g.addColorStop(1, colorBot);
    ctx.fillStyle = g;
    polyPath(path);
    ctx.fill();

    // atmospheric texture
    ctx.save();
    polyPath(path);
    ctx.clip();
    for (let i = 0; i < 260; i++) {
      const x = RR(0, W);
      const y = RR(baseY - amp, baseY + 40);
      ctx.globalAlpha = RR(0.03, 0.10);
      ctx.strokeStyle = R() > 0.5 ? '#ffffff' : '#8195ad';
      ctx.lineWidth = RR(0.5, 1.3);
      const len = RR(6, 22);
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + len, y + RR(-3, 3));
      ctx.stroke();
    }
    ctx.restore();
  }

  farRange(H * 0.66, 175, '#b3c0d1', '#c7d0da', 0.4);
  farRange(H * 0.70, 210, '#a4b3c8', '#bec9d6', 2.7);

  // ---------- main dominant angular peak ----------
  const peakBase = H * 0.74;
  // ridge polygon: sharp asymmetric summit near x=430, many shoulders
  const ridge = [
    [0, peakBase - 40], [60, peakBase - 90], [110, peakBase - 160],
    [155, peakBase - 220], [190, peakBase - 260], [215, peakBase - 320],
    [245, peakBase - 360], [270, peakBase - 400], [295, peakBase - 455],
    [318, peakBase - 500], [340, peakBase - 545], [362, peakBase - 575],
    [382, peakBase - 605], [398, peakBase - 630], [412, peakBase - 655],
    [430, 60],                       // sharp summit
    [452, 118], [466, 170], [480, 210], [498, 245],
    [512, 290], [528, 320], [540, 362],
    [556, 392], [572, 420], [592, 448],
    [616, 470], [640, 492], [668, 512],
    [700, 528], [735, 540], [770, 552],
    [810, 560], [850, 566], [890, 570],
    [940, 576], [990, 580], [1050, 582],
    [1120, 584], [W, 586]
  ];
  const mainPath = [...ridge, [W, H], [0, H]];

  // base snow fill
  const mG = ctx.createLinearGradient(0, 40, W * 0.6, peakBase);
  mG.addColorStop(0, '#fbfaf2');
  mG.addColorStop(0.28, '#f0ece1');
  mG.addColorStop(0.55, '#dadfe0');
  mG.addColorStop(0.82, '#bfc8d4');
  mG.addColorStop(1, '#a9b6c8');
  ctx.fillStyle = mG;
  polyPath(mainPath);
  ctx.fill();

  // clip and paint detail
  ctx.save();
  polyPath(mainPath);
  ctx.clip();

  // ---- irregular shadow regions (not giant triangles) ----
  function shadowPatch(seedX, seedY, radius, alpha, tone) {
    const pts = [];
    const nP = 14;
    for (let i = 0; i < nP; i++) {
      const a = (i / nP) * Math.PI * 2;
      const rr = radius * (0.55 + fbm(seedX * 0.01 + Math.cos(a) * 2, seedY * 0.01 + Math.sin(a) * 2, 3) * 0.9);
      pts.push([seedX + Math.cos(a) * rr, seedY + Math.sin(a) * rr * 1.6]);
    }
    const g = ctx.createRadialGradient(seedX, seedY, 0, seedX, seedY, radius * 1.5);
    g.addColorStop(0, `rgba(${tone},${alpha})`);
    g.addColorStop(1, `rgba(${tone},0)`);
    ctx.fillStyle = g;
    polyPath(pts);
    ctx.fill();
  }

  // shadow mass on right side of summit (irregular blobs)
  const shadowSeeds = [
    [470, 220, 90], [510, 300, 110], [545, 380, 120],
    [560, 440, 130], [600, 470, 140], [650, 500, 150],
    [710, 520, 160], [790, 540, 170], [880, 555, 180],
    [980, 570, 190], [1080, 578, 200], [1160, 582, 200],
    [520, 250, 70], [620, 440, 100], [740, 535, 120]
  ];
  for (const s of shadowSeeds) shadowPatch(s[0], s[1], s[2], 0.28, '90,104,146');
  for (const s of shadowSeeds) shadowPatch(s[0] + 10, s[1] + 8, s[2] * 0.55, 0.20, '70,88,132');

  // shadow contour strokes following slope (right half)
  for (let i = 0; i < 700; i++) {
    const t = R();
    const x = 440 + t * 740 + RR(-30, 30);
    const yy = 100 + R() * 500;
    // rough boundary under ridge
    if (yy < 90 + (x - 430) * 0.9) continue;
    ctx.globalAlpha = RR(0.05, 0.18);
    ctx.strokeStyle = R() > 0.4 ? '#7d8ab4' : '#6a78a2';
    ctx.lineWidth = RR(0.5, 1.6);
    const dx = RR(6, 26);
    ctx.beginPath();
    ctx.moveTo(x, yy);
    ctx.quadraticCurveTo(x + dx * 0.5, yy + RR(-1, 4), x + dx, yy + RR(0, 5));
    ctx.stroke();
  }

  // ---- sunlit ivory strokes on left / summit ----
  for (let i = 0; i < 900; i++) {
    const x = RR(0, 460);
    const yy = RR(60, peakBase);
    // limit to below ridge line left of summit
    ctx.globalAlpha = RR(0.05, 0.22);
    ctx.strokeStyle = R() > 0.35 ? '#fffdf2' : '#f4f0e4';
    ctx.lineWidth = RR(0.5, 1.8);
    const len = RR(8, 34);
    const ang = RR(-0.35, 0.35);
    ctx.beginPath();
    ctx.moveTo(x, yy);
    ctx.lineTo(x + Math.cos(ang) * len, yy + Math.sin(ang) * len + RR(-2, 3));
    ctx.stroke();
  }

  // ---- broken jagged slate outcrops ----
  function slateOutcrop(x0, y0, size, rot) {
    ctx.save();
    ctx.translate(x0, y0);
    ctx.rotate(rot);
    const shards = RI(4, 8);
    for (let s = 0; s < shards; s++) {
      const sx = RR(-size, size);
      const sy = RR(-size * 0.4, size * 0.4);
      const sw = RR(2, size * 0.5);
      const sh = RR(3, size * 0.8);
      const a = RR(-0.5, 0.5);
      ctx.save();
      ctx.translate(sx, sy);
      ctx.rotate(a);
      ctx.fillStyle = `rgba(${RI(38, 62)},${RI(44, 68)},${RI(58, 88)},${RR(0.55, 0.85)})`;
      ctx.beginPath();
      ctx.moveTo(-sw * 0.5, 0);
      ctx.lineTo(0, -sh);
      ctx.lineTo(sw * 0.5, 0);
      ctx.lineTo(sw * 0.2, sh * 0.3);
      ctx.lineTo(-sw * 0.2, sh * 0.25);
      ctx.closePath();
      ctx.fill();
      // highlight edge
      ctx.strokeStyle = `rgba(220,225,232,${RR(0.25, 0.55)})`;
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(-sw * 0.5, 0);
      ctx.lineTo(0, -sh);
      ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }
  for (let i = 0; i < 46; i++) {
    const x = RR(60, 500);
    const yy = RR(120, peakBase - 40);
    // avoid near summit
    if (Math.hypot(x - 430, yy - 60) < 40) continue;
    slateOutcrop(x, yy, RR(5, 16), RR(-0.4, 0.2));
  }
  for (let i = 0; i < 30; i++) {
    const x = RR(500, 1000);
    const yy = RR(300, peakBase - 20);
    slateOutcrop(x, yy, RR(4, 12), RR(-0.3, 0.3));
  }

  // ---- winding gullies (dark branching channels) ----
  function gully(x0, y0, len, tension) {
    ctx.save();
    ctx.strokeStyle = `rgba(74,88,120,${RR(0.35, 0.65)})`;
    ctx.lineWidth = RR(0.8, 2.0);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    let px = x0, py = y0;
    const steps = 10;
    for (let s = 0; s < steps; s++) {
      const nx = px + RR(-4, 6);
      const ny = py + len / steps + RR(-1, 2);
      ctx.lineTo(nx, ny);
      // branch
      if (s > 1 && s < steps - 2 && R() > 0.45) {
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(nx, ny);
        ctx.lineTo(nx + RR(-14, 14) * tension, ny + RR(-4, 6));
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(nx, ny);
      }
      px = nx; py = ny;
    }
    ctx.stroke();
    ctx.restore();
  }
  for (let i = 0; i < 26; i++) gully(RR(150, 900), RR(200, 560), RR(40, 110), RR(0.5, 1.0));

  // ---- snow channels (bright winding) ----
  for (let i = 0; i < 22; i++) {
    const x0 = RR(250, 780);
    const y0 = RR(120, 460);
    ctx.save();
    ctx.strokeStyle = `rgba(255,252,240,${RR(0.25, 0.55)})`;
    ctx.lineWidth = RR(1.5, 3.8);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    let px = x0, py = y0;
    for (let s = 0; s < 8; s++) {
      px += RR(-6, 6);
      py += RR(4, 12);
      ctx.lineTo(px, py);
    }
    ctx.stroke();
    ctx.restore();
  }

  // ---- fine contour-following strokes over entire peak ----
  for (let i = 0; i < 1400; i++) {
    const x = RR(20, W);
    // y range depends roughly on ridge slope
    const yy = RR(45, 590);
    const leftness = x < 430;
    ctx.globalAlpha = RR(0.04, 0.14);
    ctx.strokeStyle = leftness ? '#fbf7ea' : '#8a96b6';
    ctx.lineWidth = RR(0.4, 1.2);
    const len = RR(4, 18);
    const ang = RR(-0.25, 0.25) + (leftness ? 0.1 : -0.05);
    ctx.beginPath();
    ctx.moveTo(x, yy);
    ctx.lineTo(x + Math.cos(ang) * len, yy + Math.sin(ang) * len);
    ctx.stroke();
  }

  // low-contrast correlated snow texture (fbm tinting)
  ctx.globalCompositeOperation = 'overlay';
  for (let i = 0; i < 500; i++) {
    const x = RR(0, W), yy = RR(40, 600);
    const nv = fbm(x * 0.01, yy * 0.01, 4);
    ctx.globalAlpha = 0.06;
    ctx.fillStyle = nv > 0.5 ? 'rgba(200,210,228,0.5)' : 'rgba(255,255,250,0.5)';
    ctx.beginPath();
    ctx.arc(x, yy, RR(2, 7), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';

  ctx.restore();

  // ---- crisp ridge line highlights along outline ----
  ctx.save();
  ctx.strokeStyle = 'rgba(255,253,244,0.75)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  for (let i = 6; i <= 16; i++) {
    const p = ridge[i];
    if (i === 6) ctx.moveTo(p[0], p[1]); else ctx.lineTo(p[0], p[1]);
  }
  ctx.stroke();
  // thin dark line right of summit edge
  ctx.strokeStyle = 'rgba(78,90,120,0.35)';
  ctx.lineWidth = 1.0;
  ctx.beginPath();
  const sp = ridge.find(p => p[0] === 430);
  let ppx = sp[0], ppy = sp[1];
  for (let i = 0; i < 14; i++) {
    ppx += RR(6, 14);
    ppy += RR(12, 26);
    ctx.lineTo(ppx, ppy);
  }
  ctx.stroke();
  ctx.restore();

  // ---------- secondary peaks ----------
  function secondary(pts, shadowRight) {
    const path = [...pts, [W, H], [0, H]];
    const g = ctx.createLinearGradient(0, Math.min(...pts.map(p => p[1])), 0, peakBase + 40);
    g.addColorStop(0, '#f1f0e6');
    g.addColorStop(0.5, '#cdd4dc');
    g.addColorStop(1, '#b2bdcb');
    ctx.fillStyle = g;
    polyPath(path);
    ctx.fill();

    ctx.save();
    polyPath(path);
    ctx.clip();
    // texture strokes
    for (let i = 0; i < 400; i++) {
      const x = RR(600, W);
      const yy = RR(300, peakBase);
      ctx.globalAlpha = RR(0.05, 0.18);
      ctx.strokeStyle = shadowRight && x > 850 ? '#7c8aac' : '#fffcea';
      ctx.lineWidth = RR(0.4, 1.3);
      const len = RR(6, 22);
      ctx.beginPath();
      ctx.moveTo(x, yy);
      ctx.lineTo(x + len, yy + RR(-2, 3));
      ctx.stroke();
    }
    // slate accents
    for (let i = 0; i < 22; i++) {
      slateOutcrop(RR(700, W - 40), RR(360, peakBase - 20), RR(4, 10), RR(-0.3, 0.3));
    }
    // irregular shadow patch on right
    if (shadowRight) {
      for (let i = 0; i < 5; i++) {
        shadowPatch(880 + i * 60, 460 + i * 20, 90, 0.22, '90,104,146');
      }
    }
    ctx.restore();
  }

  secondary([
    [650, peakBase], [720, peakBase - 60], [770, peakBase - 130],
    [820, peakBase - 170], [855, peakBase - 150], // secondary summit
    [892, peakBase - 120], [930, peakBase - 140],
    [980, peakBase - 90], [1040, peakBase - 60], [1120, peakBase - 30], [W, peakBase - 15]
  ], true);

  // ---------- valley haze ----------
  const haze = ctx.createLinearGradient(0, H * 0.55, 0, H * 0.78);
  haze.addColorStop(0, 'rgba(210,216,222,0.0)');
  haze.addColorStop(0.55, 'rgba(206,214,222,0.42)');
  haze.addColorStop(1, 'rgba(196,208,220,0.78)');
  ctx.fillStyle = haze;
  ctx.fillRect(0, H * 0.55, W, H * 0.25);

  // ---------- mid terrain ----------
  function terrainBand(yTop, yBot, cTop, cBot, amp, offs) {
    const pts = [];
    for (let i = 0; i <= 40; i++) {
      const t = i / 40;
      const x = t * W;
      const y = yTop + Math.sin(t * 4 + offs) * amp * 0.3 + (fbm(t * 6 + offs, offs, 4) - 0.5) * amp;
      pts.push([x, y]);
    }
    const path = [...pts, [W, H], [0, H]];
    const g = ctx.createLinearGradient(0, yTop - amp, 0, yBot);
    g.addColorStop(0, cTop);
    g.addColorStop(1, cBot);
    ctx.fillStyle = g;
    polyPath(path);
    ctx.fill();
  }
  terrainBand(H * 0.72, H * 0.88, '#dbe3e8', '#c5cfdb', 26, 1.2);
  terrainBand(H * 0.76, H * 0.92, '#e5eaec', '#cdd6e0', 20, 4.5);

  // ---------- foreground snowbank ----------
  const fgPts = [];
  const nf = 40;
  for (let i = 0; i <= nf; i++) {
    const t = i / nf;
    const x = t * W;
    const y = H * 0.86
      + Math.sin(t * 3.4 + 0.3) * 20
      + Math.sin(t * 7.8 + 1.4) * 11
      + (fbm(t * 5 + 0.7, 0.9, 4) - 0.5) * 34;
    fgPts.push([x, y]);
  }
  const fullFg = [...fgPts, [W, H], [0, H]];
  const fgGrad = ctx.createLinearGradient(0, H * 0.84, 0, H);
  fgGrad.addColorStop(0, '#f0f3f4');
  fgGrad.addColorStop(0.55, '#e1e8ee');
  fgGrad.addColorStop(1, '#c6d1dc');
  ctx.fillStyle = fgGrad;
  polyPath(fullFg);
  ctx.fill();

  ctx.save();
  polyPath(fullFg);
  ctx.clip();
  // sastrugi
  for (let i = 0; i < 1400; i++) {
    const x = RR(0, W);
    const yy = RR(H * 0.85, H);
    const ang = RR(-0.15, 0.15) + Math.sin(x * 0.02) * 0.15;
    ctx.globalAlpha = RR(0.05, 0.30);
    ctx.strokeStyle = R() > 0.45 ? '#ffffff' : '#9cadc2';
    ctx.lineWidth = RR(0.4, 1.3);
    const len = RR(4, 20);
    ctx.beginPath();
    ctx.moveTo(x, yy);
    ctx.lineTo(x + Math.cos(ang) * len, yy + Math.sin(ang) * len);
    ctx.stroke();
  }
  // shadow dips
  for (let i = 0; i < 40; i++) {
    const x = RR(0, W);
    const yy = RR(H * 0.87, H);
    ctx.globalAlpha = 0.08;
    ctx.fillStyle = '#8fa0b8';
    ctx.beginPath();
    ctx.ellipse(x, yy, RR(30, 90), RR(4, 10), 0, 0, Math.PI * 2);
    ctx.fill();
  }
  // low foreground undulations
  for (let i = 0; i < 22; i++) {
    const x = RR(0, W);
    const yy = RR(H * 0.9, H);
    ctx.globalAlpha = 0.10;
    ctx.fillStyle = R() > 0.5 ? '#ffffff' : '#a9b6c8';
    ctx.beginPath();
    ctx.ellipse(x, yy, RR(40, 130), RR(3, 8), RR(-0.05, 0.05), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();

  // ---------- organic evergreens ----------
  function branch(sx, sy, ex, ey, w, col) {
    ctx.strokeStyle = col;
    ctx.lineWidth = w;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.quadraticCurveTo((sx + ex) / 2, (sy + ey) / 2 - Math.abs(ex - sx) * 0.06, ex, ey);
    ctx.stroke();
  }

  function drawEvergreen(bx, by, height, depth) {
    const trunkW = Math.max(1.2, height * 0.022);
    const trunkTop = by - height * 0.94;
    // trunk
    ctx.strokeStyle = `rgb(${18 + depth * 12},${14 + depth * 10},${10 + depth * 6})`;
    ctx.lineWidth = trunkW;
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.quadraticCurveTo(bx + height * 0.02, by - height * 0.45, bx + RR(-1, 1), trunkTop);
    ctx.stroke();

    const tiers = 11 + Math.floor(R() * 4);
    const dark = `rgb(${14 + depth * 12},${30 + depth * 10},${24 + depth * 8})`;
    const mid = `rgb(${24 + depth * 14},${44 + depth * 12},${32 + depth * 10})`;
    const lite = `rgba(${120 + depth * 40},${140 + depth * 30},${104 + depth * 30},${0.7 + depth * 0.2})`;

    // branches, top-down so lower overlaps upper
    for (let t = 0; t < tiers; t++) {
      const f = t / (tiers - 1);
      const yBase = by - height * (0.10 + f * 0.82);
      const side = (t % 2 === 0) ? 1 : -1;
      const spread = height * (0.32 - f * 0.24) * (0.7 + R() * 0.5);
      const droop = spread * (0.35 + R() * 0.25);
      const len = spread * (0.55 + R() * 0.55);

      // main side branch
      const ex = bx + side * len;
      const ey = yBase + droop;
      branch(bx, yBase, ex, ey, Math.max(0.9, trunkW * (1.6 - f)), dark);

      // secondary twigs
      const twigs = 3 + Math.floor(R() * 3);
      for (let k = 0; k < twigs; k++) {
        const u = 0.3 + k / twigs * 0.7;
        const sx = bx + side * len * u;
        const sy = yBase + droop * u;
        const tx = sx + side * RR(-4, 8) + RR(-6, 6);
        const ty = sy + RR(-8, -2);
        branch(sx, sy, tx, ty, Math.max(0.5, trunkW * (0.7 - f * 0.4)), R() > 0.5 ? dark : mid);
        // needle tufts
        if (R() > 0.35) {
          ctx.fillStyle = `rgba(${18 + depth * 10},${38 + depth * 12},${26 + depth * 8},${0.85})`;
          ctx.beginPath();
          ctx.ellipse(sx + side * 2, sy, RR(3, 7), RR(1.5, 3), RR(-0.3, 0.3), 0, Math.PI * 2);
          ctx.fill();
        }
      }

      // occasional snow clump on top of branch
      if (R() > 0.55) {
        ctx.fillStyle = `rgba(238,242,245,${0.55 + R() * 0.35})`;
        ctx.beginPath();
        ctx.ellipse(bx + side * len * RR(0.4, 0.9), yBase + droop * 0.6 + RR(-2, 2), RR(3, 9), RR(1, 2.4), RR(-0.2, 0.2), 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // top spire with snow
    ctx.strokeStyle = mid;
    ctx.lineWidth = Math.max(0.6, trunkW * 0.8);
    ctx.beginPath();
    ctx.moveTo(bx, by - height * 0.75);
    ctx.lineTo(bx + RR(-1, 1), by - height);
    ctx.stroke();
    ctx.fillStyle = `rgba(242,246,248,${0.7 + depth * 0.2})`;
    ctx.beginPath();
    ctx.ellipse(bx, by - height + 1, RR(2, 4), RR(1, 2), 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // cluster
  const cluster = [
    { x: 1010, y: H * 0.945, h: 170 },
    { x: 1055, y: H * 0.96, h: 130 },
    { x: 1105, y: H * 0.95, h: 200 },
    { x: 1148, y: H * 0.965, h: 115 },
    { x: 1178, y: H * 0.94, h: 155 },
    { x: 1082, y: H * 0.995, h: 240 },
    { x: 962, y: H * 0.968, h: 95 },
    { x: 1130, y: H * 0.99, h: 210 },
  ];
  cluster.sort((a, b) => a.h - b.h);
  for (const t of cluster) drawEvergreen(t.x, t.y, t.h, t.h / 260);

  // ---------- finish: light + vignette ----------
  ctx.save();
  ctx.globalCompositeOperation = 'soft-light';
  const lg = ctx.createLinearGradient(W * 0.1, 0, W * 0.85, H);
  lg.addColorStop(0, 'rgba(255,248,232,0.22)');
  lg.addColorStop(0.5, 'rgba(228,236,246,0.05)');
  lg.addColorStop(1, 'rgba(170,188,214,0.16)');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();

  ctx.save();
  const vg = ctx.createRadialGradient(W * 0.5, H * 0.42, H * 0.32, W * 0.5, H * 0.5, H * 0.98);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(30,42,58,0.22)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();

})();
